// Entrée attendue (corps JSON du webhook) : { contrat_id, pdf_url }
const corps = $("01 · Contrat et PDF").first().json.body ?? {};
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
const contrat_id = typeof corps.contrat_id === 'string' ? corps.contrat_id.trim() : '';
const pdf_url = typeof corps.pdf_url === 'string' ? corps.pdf_url.trim() : '';

const erreurs = [];
if (!UUID.test(contrat_id)) erreurs.push('contrat_id : UUID attendu');
if (!/^https:\/\/\S+$/.test(pdf_url)) erreurs.push('pdf_url : URL signée en https attendue');
if ('document_id' in corps || 'video_id' in corps) {
  erreurs.push('document_id et video_id ne sont plus acceptés : envoyer contrat_id et pdf_url');
}

// Clé d'idempotence : contrat + chemin du PDF, sans la signature de l'URL.
const cle_idempotence = 'contrat:' + contrat_id + ':' + pdf_url.split('?')[0];

return [{ json: { valide: erreurs.length === 0, erreurs, contrat_id, pdf_url, cle_idempotence } }];

// Sortie du nœud HTTP : { statusCode, body } ; ou { error } si le service est injoignable.
const reponse = $json;
const statut = typeof reponse.statusCode === 'number' ? reponse.statusCode : null;
const corps = reponse.body && typeof reponse.body === 'object' ? reponse.body : {};
const entree = $("02 · Contrôler l’entrée").first().json;

let cas = 'erreur';
if (statut === 200 && Array.isArray(corps.obligations)) cas = 'resultat';
else if (statut === 202) cas = 'accepte';
else if (statut === 501) cas = 'stub'; // le service vision n'est encore qu'un stub

let detail = null;
if (cas === 'erreur') {
  detail = statut === null ? 'service vision injoignable' : 'réponse inattendue du service vision (HTTP ' + statut + ')';
}

return [{
  json: {
    cas,
    est_resultat: cas === 'resultat',
    est_accepte: cas === 'accepte',
    est_stub: cas === 'stub',
    statut_http: statut,
    contrat_id: entree.contrat_id,
    extraction: cas === 'resultat' ? corps : null,
    detail,
  },
}];

// Identifiant déterministe au format UUID (version 8) : rejouer le workflow réécrit les mêmes lignes.
function idDeterministe(texte) {
  let h = '';
  for (let k = 0; k < 4; k++) {
    let x = 0x811c9dc5;
    const s = k + ':' + texte;
    for (let i = 0; i < s.length; i++) { x ^= s.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
    h += x.toString(16).padStart(8, '0');
  }
  const variante = ((parseInt(h[16], 16) & 0x3) | 0x8).toString(16);
  return h.slice(0, 8) + '-' + h.slice(8, 12) + '-8' + h.slice(13, 16) + '-' + variante + h.slice(17, 20) + '-' + h.slice(20, 32);
}

// Extraction attendue du service vision :
// { assureur, formule, reference_cg, obligations: [ { type, element, seuil, unite,
//   texte_court, citation, clause, page, citation_retrouvee } ] }
const TYPES = ['prevention', 'inoccupation', 'exclusion', 'garantie', 'franchise', 'plafond'];
const texte = (valeur) => (typeof valeur === 'string' ? valeur.trim() : '');
const { contrat_id, extraction } = $json;

const obligations = [];
const rejetees = [];
for (const o of extraction.obligations ?? []) {
  const clause = texte(o.clause);
  const page = Number.isInteger(o.page) && o.page >= 1 ? o.page : null;
  const motifs = [];
  if (page === null) motifs.push('page non retrouvée dans le PDF');
  if (!clause) motifs.push('clause manquante');
  if (!texte(o.citation)) motifs.push('citation manquante');
  if (o.citation_retrouvee !== true) motifs.push('citation non vérifiée dans le PDF');
  if (!TYPES.includes(o.type)) motifs.push('type d\'obligation inconnu');
  if (motifs.length > 0) {
    rejetees.push({ motifs, texte_court: texte(o.texte_court) || null, clause: clause || null, page });
    continue;
  }
  const element = texte(o.element) || null;
  obligations.push({
    id: idDeterministe([contrat_id, o.type, element, clause, page].join('|')),
    contrat_id,
    type: o.type,
    element,
    seuil: o.seuil ?? null,
    unite: texte(o.unite) || null,
    texte_court: texte(o.texte_court) || null,
    citation: texte(o.citation) || null,
    clause,
    page,
    citation_retrouvee: o.citation_retrouvee === true,
  });
}

return [{
  json: {
    contrat_id,
    assureur: texte(extraction.assureur) || null,
    formule: texte(extraction.formule) || null,
    reference_cg: texte(extraction.reference_cg) || null,
    obligations,
    rejetees,
  },
}];

// Identifiant déterministe au format UUID (version 8) : rejouer le workflow réécrit les mêmes lignes.
function idDeterministe(texte) {
  let h = '';
  for (let k = 0; k < 4; k++) {
    let x = 0x811c9dc5;
    const s = k + ':' + texte;
    for (let i = 0; i < s.length; i++) { x ^= s.charCodeAt(i); x = Math.imul(x, 0x01000193) >>> 0; }
    h += x.toString(16).padStart(8, '0');
  }
  const variante = ((parseInt(h[16], 16) & 0x3) | 0x8).toString(16);
  return h.slice(0, 8) + '-' + h.slice(8, 12) + '-8' + h.slice(13, 16) + '-' + variante + h.slice(17, 20) + '-' + h.slice(20, 32);
}

// Nœuds Clause et arêtes IMPOSE → Règle (v3, section 7).
const entree = $("05 · Filtrer les clauses").first().json;

// Règles du graphe : corps de la lecture Supabase quand le nœud 06 est actif, sinon aucune.
const lecture = $json;
const regles = Array.isArray(lecture.body) ? lecture.body : [];
const parElement = new Map();
for (const regle of regles) {
  const fiche = regle.regles ?? {};
  // Seules les règles validées comptent : le verdict ne vient jamais d'une règle proposée.
  if (fiche.statut_validation !== 'validee' || !fiche.element) continue;
  if (!parElement.has(fiche.element)) parElement.set(fiche.element, []);
  parElement.get(fiche.element).push({ noeud_id: regle.id, code: fiche.code, version: fiche.version });
}

const noeuds = [];
const aretes = [];
const sans_regle = [];
for (const o of entree.obligations) {
  const noeud_id = idDeterministe('Clause|' + o.id);
  noeuds.push({
    id: noeud_id,
    type: 'Clause',
    libelle: o.texte_court || o.clause,
    proprietes: {
      obligation_id: o.id,
      clause: o.clause,
      page: o.page,
      citation: o.citation,
      type_obligation: o.type,
      element: o.element,
      seuil: o.seuil,
      unite: o.unite,
    },
    contrat_id: entree.contrat_id, // nœud privé : visible du seul propriétaire du contrat (RLS)
    regle_id: null,
    texte: [o.texte_court, o.citation].filter(Boolean).join(' — ') || o.clause,
  });

  const cibles = o.element ? parElement.get(o.element) ?? [] : [];
  if (cibles.length === 0) sans_regle.push({ clause: o.clause, page: o.page, element: o.element });
  for (const cible of cibles) {
    aretes.push({
      source_id: noeud_id,
      cible_id: cible.noeud_id,
      relation: 'IMPOSE',
      proprietes: { clause: o.clause, page: o.page, code_regle: cible.code, version_regle: cible.version },
    });
  }
}

return [{ json: { contrat_id: entree.contrat_id, noeuds, aretes, sans_regle, regles_lues: regles.length } }];

// Réunit les lignes à écrire. Les colonnes suivent la v3 (section 9) et l'issue #1.
const entree = $("05 · Filtrer les clauses").first().json;
const graphe = $("07 · Préparer le graphe").first().json;
const dimension = $("Config").first().json.EMBEDDING_DIMENSION;

// Vecteurs : corps de la réponse Hugging Face quand le nœud 08 est actif, sinon aucun.
const reponse = $json;
const vecteurs = Array.isArray(reponse.body) ? reponse.body : [];
const valides = graphe.noeuds.map((_, i) => Array.isArray(vecteurs[i]) && vecteurs[i].length === dimension);

let embeddings = 'non_calcules';
if (graphe.noeuds.length > 0 && valides.every(Boolean)) embeddings = 'calcules';
else if (vecteurs.length > 0) embeddings = 'refuses'; // absent, incomplet ou d'une autre dimension

// Toutes les lignes d'un même envoi portent les mêmes colonnes : la colonne embedding
// n'est écrite que si tous les vecteurs sont valides, pour ne jamais effacer un vecteur existant.
const noeuds = graphe.noeuds.map((noeud, i) => {
  const { texte, ...ligne } = noeud;
  return embeddings === 'calcules' ? { ...ligne, embedding: vecteurs[i] } : ligne;
});

return [{
  json: {
    contrat_id: entree.contrat_id,
    assureur: entree.assureur,
    formule: entree.formule,
    reference_cg: entree.reference_cg,
    obligations: entree.obligations,
    rejetees: entree.rejetees,
    noeuds,
    aretes: graphe.aretes,
    sans_regle: graphe.sans_regle,
    embeddings,
  },
}];
